body,td,div,.p,a,font,span \x7b
font-family: arial,sans-serif;
\x7d

.tl \x7b
	background-image: url(//www.gmail.com/mail/help/images/corner_tl_sharp.gif);
	background-position: top left;
	background-repeat: no-repeat;
\x7d

.tr \x7b
	background-image: url(//www.gmail.com/mail/help/images/corner_tr_sharp.gif);
	background-position:top right;
	background-repeat:no-repeat;
\x7d

.bl \x7b
	background-image: url(//www.gmail.com/mail/help/images/corner_bl_sharp.gif);
	background-position: bottom left;
	background-repeat: no-repeat;
\x7d

.br \x7b
	background-image: url(//www.gmail.com/mail/help/images/corner_br_sharp.gif);
	background-position: bottom right;
	background-repeat: no-repeat;
\x7d

.bubble \x7b
	background-color: #c3d9ff;
\x7d
.i \x7b margin-left: 1em; margin-right: 1em; \x7d

.link \x7b
 color: blue;
 cursor: pointer;
 text-decoration: underline;
\x7d

.chat-logo \x7b
 width: 90px;
 height: 40px;
 padding: 4px 16px 4px 4px;
\x7d

.gmail-logo \x7b
 width: 143px;
 height: 59px;
\x7d

.banner \x7b
 background-color: #fbe9e7;
 color: #a52714;
\x7d

#unsupported_browser .unsupported_browser-warning \x7b
 color: #b3261e;
 font-weight: 600;
 line-height: 18px;
\x7d

#unsupported_browser \x7b
 display: none;
\x7d

#unsupported_browser.unsupported_browser_show \x7b
 display: block;
\x7d

